vec3 HUEtoRGB(in float hue)
{
    vec3 rgb = abs(hue * 6. - vec3(3, 2, 4)) * vec3(1, -1, -1) + vec3(-1, 2, 2);
    return clamp(rgb, 0., 1.);
}
vec3 HSVtoRGB(in vec3 hsv)
{
    vec3 rgb = HUEtoRGB(hsv.x);
    return ((rgb - 1.) * hsv.y + 1.) * hsv.z;
}
vec3 RGBtoHSV(vec3 c) {
    float maxC = max(c.r, max(c.g, c.b));
    float minC = min(c.r, min(c.g, c.b));
    float delta = maxC - minC;

    float h = 0.0;
    if (delta > 0.0) {
        if (maxC == c.r) {
            h = mod((c.g - c.b) / delta, 6.0);
        } else if (maxC == c.g) {
            h = ((c.b - c.r) / delta) + 2.0;
        } else {
            h = ((c.r - c.g) / delta) + 4.0;
        }
        h *= 60.0;
    }

    float s = (maxC > 0.0) ? (delta / maxC) : 0.0;
    float v = maxC;

    return vec3(h, s, v);
}
// Compute hue-based similarity (higher = closer)
float presence(vec3 A, vec3 B) {
    vec3 hsvA = RGBtoHSV(A);
    float wlA = 650.-250./270.*hsvA.x;
    vec3 hsvB = RGBtoHSV(B);
    float wlB = 650.-250./270.*hsvB.x;

    float dist1 = abs(wlA-wlB);
    float t1 = 1.-dist1*.015;
    t1 = clamp(t1,0.,1.);
    t1 = pow(t1, 1.5);

    float dist2 = abs(wlA-wlB-340.);
    float t2 = 1.-dist2*.015;
    t2 = clamp(t2,0.,1.);
    t2 = pow(t2, 1.5);

    float t = t1+t2;
    t = mix(t, 1., 1.-hsvB.y);
    t *= hsvB.z;

    return clamp(t,0.,1.);
}

vec3 wl_rgb(float w)
{
    vec3 hsv = vec3(
        (270./250.*(650.-w))/360.,
        1.,
        .75
    );
    return HSVtoRGB(hsv);
}

