vec3 getRayDir(vec3 ro, vec3 wo, vec2 uv, float FOV) {
    float t = tan(FOV*3.14159/180.);
    vec3 f = normalize(wo-ro),
        r = normalize(cross(vec3(0,1,0),f)),
        u = cross(f,r),
        rd = f+r*uv.x*t+u*uv.y*t;
    return normalize(rd);
}
mat3 rotateX(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(1, 0, 0),
        vec3(0, c, -s),
        vec3(0, s, c)
    );
}
mat3 rotateY(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, 0, s),
        vec3(0, 1, 0),
        vec3(-s, 0, c)
    );
}
mat3 rotateZ(float theta) {
    float c = cos(theta);
    float s = sin(theta);
    return mat3(
        vec3(c, -s, 0),
        vec3(s, c, 0),
        vec3(0, 0, 1)
    );
}
mat3 identity() {
    return mat3(
        vec3(1, 0, 0),
        vec3(0, 1, 0),
        vec3(0, 0, 1)
    );
}
mat2 rotate(float angle) {
    float s = sin(angle);
    float c = cos(angle);
    return mat2(
        c,-s,
        s,c
    );
}
vec3 rot3D(vec3 p, float pitch, float yaw) {
    p.zy *= rotate(pitch);
    p.xz *= rotate(yaw);
    return p;
}
