// Return the i-th term of the golden ratio sequence
float goldenSequence(uint i) {
    return float(2654435769u * i) / 4294967296.0;
}
// Return the i-th vector of Martin Roberts' R2 sequence
// http://extremelearning.com.au/unreasonable-effectiveness-of-quasirandom-sequences/
vec2 plasticSequence(uint i) {
    return vec2(3242174889u * i, 2447445414u * i) / 4294967296.0;
}
vec3 sequence3D(uint i) {
    return vec3(plasticSequence(i), goldenSequence(i));
}

vec3 toroidalJitter(vec3 x, vec3 jitter) {
    return 2.0 * abs(fract(x + jitter) - 0.5);
}
float hash11(inout uint state)
{
    state ^= 2747636419u;
    state *= 2654435769u;
    state ^= state >> 16;
    state *= 2654435769u;
    state ^= state >> 16;
    state *= 2654435769u;
    return float(state) / 4294967295.;
}
vec3 hash13(inout uint state)
{
	return vec3(hash11(state), hash11(state), hash11(state));
}
vec3 randomNormal(inout uint state) {
    vec3 theta = 6.28318531*hash13(state);
    vec3 rho = sqrt(-2.*log(hash13(state)));
    return normalize(rho*cos(theta));
}
//IOR
float dynamicIOR(float w, float IOR, float A) {
    return IOR+A/(w*w);
