//DISTANCES
vec4 rayBox(vec3 ro, vec3 rd, vec3 ce, vec3 b, mat3 transform, inout bool hit) 
{
    ro -= ce;
    ro *= inverse(transform);
    rd *= inverse(transform);
    vec3 m = 1.0/rd; // can precompute if traversing a set of aligned boxes
    vec3 n = m*ro;   // can precompute if traversing a set of aligned boxes
    vec3 k = abs(m)*b;
    vec3 t1 = -n - k;
    vec3 t2 = -n + k;
    float tN = max( max( t1.x, t1.y ), t1.z );
    float tF = min( min( t2.x, t2.y ), t2.z );
    if( tN>tF || tF<0.0) return vec4(-1.); // no intersection
    vec3 normal = (tN>0.0) ? step(vec3(tN),t1) : // ro ouside the box
                           step(t2,vec3(tF));  // ro inside the box
    normal *= -sign(rd);
    float t = tN;
    if (tN < 0.) {
        t = tF;
    }
    if (t > 0.) hit = true;

    normal *= transpose(inverse(transform));
    return vec4(normal, t);
}
traceData Box(vec3 ro, vec3 rd, vec3 ce, vec3 b, mat3 transform, int matIndex) {
    bool hit = false;
    vec4 dat = rayBox(ro, rd, ce, b, transform, hit);
    traceData tdat;
    tdat.dist = dat.w;
    tdat.normal = dat.xyz;
    tdat.matIndex = matIndex;
    tdat.hit = hit;
    return tdat;
}

vec4 raySphere(vec3 ro, vec3 rd, vec3 ce, float r, inout bool hit) {
    hit = false;
    vec3 oc = ro - ce;
    float b = dot( oc, rd );
    vec3 qc = oc - b*rd;
    float h = r*r - dot( qc, qc );
    if( h<0.0 ) return vec4(-1.); // no intersection
    h = sqrt(h);
    vec2 dist = vec2(-b-h, -b+h);
    vec3 normal = normalize(ro + rd*dist.x - ce);

    float t = dist.x;
    if (dist.x < 0.) {
        t = dist.y;
        normal = -normalize(ro + rd*t - ce);
    }
    if (t > 0.) hit = true;

    return vec4(normal, t);
}
traceData Sphere(vec3 ro, vec3 rd, vec3 ce, float r, int matIndex) {
    bool hit = false;
    //check if hit bounding box first
    rayBox(ro, rd, ce, vec3(r), identity(), hit);
    if (!hit) return notHit();
    hit = false;
    //if hit bounding box calculate actual collision
    vec4 dat = raySphere(ro, rd, ce, r, hit);
    traceData tdat;
    tdat.dist = dat.w;
    tdat.normal = dat.xyz;
    tdat.matIndex = matIndex;
    tdat.hit = hit;
    return tdat;
}
vec4 rayPlane(vec3 ro, vec3 rd, vec3 ce, vec3 n, inout bool hit) {
    hit = false;
    float d = dot(ro-ce,n);
    float Q = -d/dot(rd,n);
    if (Q > 0.) hit = true;
    return vec4(n, Q);
}
traceData Plane(vec3 ro, vec3 rd, vec3 ce, vec3 n, int matIndex) {
    bool hit = false;
    vec4 dat = rayPlane(ro, rd, ce, n, hit);
    traceData tdat;
    tdat.dist = dat.w;
    tdat.normal = dat.xyz;
    tdat.matIndex = matIndex;
    tdat.hit = hit;
