}
vec4 rayRectangle(vec3 ro, vec3 rd, vec3 ce, vec3 n, vec2 b, inout bool hit) {
    hit = false;
    float d = dot(ro-ce,n);
    if (d < 0.) return vec4(n, 0.);
    float Q = -d/dot(rd,n);
    vec3 up = vec3(0.,1.,0.);
    if (abs(dot(n,up)) >= .9) up = vec3(1.,0.,0.);
    vec3 left = cross(n,up);
    vec3 p = ro+rd*Q-ce;
    float x = dot(left,p);
    float y = dot(up,p);

    bool insideRect = abs(x/b.x+y/b.y)+abs(x/b.x-y/b.y) <= 2.;
    if (Q > 0. && insideRect) hit = true;
    return vec4(n, Q);
}
traceData Rectangle(vec3 ro, vec3 rd, vec3 ce, vec3 n, vec2 b, int matIndex) {
