vec4 rayUncappedCylinder( in vec3 ro, in vec3 rd, in vec3 pa, in vec3 pb, float ra ) 
{
    vec3  ba = pb - pa;
    vec3  oc = ro - pa;

    float baba = dot(ba,ba);
    float bard = dot(ba,rd);
    float baoc = dot(ba,oc);

    float k2 = baba            - bard*bard;
    float k1 = baba*dot(oc,rd) - baoc*bard;
    float k0 = baba*dot(oc,oc) - baoc*baoc - ra*ra*baba;

    /*
    // in case you really need to handle parallel raycasts
    if( k2==0.0 )
    {
        float ta = -dot(ro-pa,ba)/bard;
        float tb = ta + baba/bard;

        vec4 pt = (bard>0.0) ? vec4(pa,-ta) : vec4(pb,tb);

        vec3 q = ro + rd*abs(pt.w) - pt.xyz;
        if( dot(q,q)>ra*ra ) return vec4(-1.0);

        return vec4( abs(pt.w), sign(pt.w)*ba/sqrt(baba) );
    }
    */

    float h = k1*k1 - k2*k0;
    if( h<0.0 ) return vec4(-1.0);
    h = sqrt(h);
    float tNear = (-k1-h)/k2;
    float tFar = (-k1+h)/k2;

    // body
    float y = baoc + tNear*bard;
    if( y>0.0 && y<baba && tNear < tFar && tNear > 0.) return vec4((oc+tNear*rd - ba*y/baba)/ra, tNear);
    y = baoc + tFar*bard;
    if( y>0.0 && y<baba && tFar > tNear) return vec4(-(oc+tFar*rd - ba*y/baba)/ra, tFar);

    return vec4(-1.0);
}
traceData UncappedCylinder(vec3 ro, vec3 rd, vec3 pa, vec3 pb, float r, mat3 transform, int matIndex) {
    bool hit = false;
    vec3 pa2 = (pa-(pa+pb)*.5)*(transform)+(pa+pb)*.5;
    pb = (pb-(pa+pb)*.5)*(transform)+(pa+pb)*.5;
    pa = pa2;
    vec4 dat = rayUncappedCylinder(ro, rd, pa, pb, r);
    if (dat.w > 0.) hit = true;
    traceData tdat;
    tdat.dist = dat.w;
    tdat.normal = dat.xyz;
    tdat.matIndex = matIndex;
    tdat.hit = hit;
    return tdat;
}
float rayDisk( in vec3 ro, in vec3 rd, vec3 c, vec3 n, float r, bool oneSided )
{
    vec3  o = ro - c;
    float d = dot(n,o);
    if (d < 0. && oneSided) return -1.;
    float t = -d/dot(rd,n);
    vec3  q = o + rd*t;
    return (dot(q,q)<r*r) ? t : -1.0;
}
traceData Disk(vec3 ro, vec3 rd, vec3 ce, vec3 n, float r, bool oneSided, int matIndex) {
    bool hit = false;
    vec4 dat = vec4(n, rayDisk(ro, rd, ce, n, r, oneSided));
    if (dat.w > 0.) hit = true;
    traceData tdat;
    tdat.dist = dat.w;
    tdat.normal = dat.xyz;
    tdat.matIndex = matIndex;
    tdat.hit = hit;
    return tdat;
}
float rayDiskTorus( in vec3 ro, in vec3 rd, vec3 c, vec3 n, float R, float r, bool oneSided )
{
    vec3  o = ro - c;
    float d = dot(n,o);
    if (d < 0. && oneSided) return -1.;
    float t = -d/dot(rd,n);
    vec3  q = o + rd*t;
    float l = dot(q,q);
    return (l<R*R && l>r*r) ? t : -1.0;
}
traceData DiskTorus(vec3 ro, vec3 rd, vec3 ce, vec3 n, float R, float r, bool oneSided, int matIndex) {
    bool hit = false;
    vec4 dat = vec4(n, rayDiskTorus(ro, rd, ce, n, R, r, oneSided));
    if (dat.w > 0.) hit = true;
    traceData tdat;
    tdat.dist = dat.w;
    tdat.normal = dat.xyz;
    tdat.matIndex = matIndex;
    tdat.hit = hit;
    return tdat;
}

#define ONE int(min(1.,float(iFrame)+1.))

#define SAMPLES 25
#define MAX_BOUNCES 20
#define EPSILON 1e-3
#define BLOBBY 0

#define BLOOM_CHANCE .002

#define SKYBOX_BRIGHTNESS .03

#define FOG_DENSITY .0005
#define FOG_COLOR vec3(1.000,1.000,1.000)
#define MAX_FOG_BOUNCES_INTERNAL 1
#define MAX_FOG_BOUNCES_EXTERNAL 1

#define RENDER_WAVELENGTHS 1

#define T 6.39 //REPLACE WITH iTime and set TEMPORAL_RENDER IN BUFFERB TO 0 FOR REALTIME
