vec3 sky(vec3 rd) {
    return texture(iChannel0, rd).rgb;
}
traceData trace(vec3 ro, vec3 rd, inout bool hit) {
    traceData scene;
    #if SCENE == 0
    Add(scene, Plane(ro, rd, vec3(0., -1e-2, 0.), vec3(0., 1., 0.), CHECKERED));
    Add(scene, UncappedCylinder(ro, rd, vec3(-2., 1., 0.), vec3(2., 1., 0.), 1., rotateY(T), METAL));
    Add(scene, Box(ro, rd, vec3(sinpow(T,.2)*4., 1., 0.), vec3(.2), identity(), LIGHT));
    #elif SCENE == 1
    Add(scene, Sphere(ro, rd, vec3(0., 0., 0.), 1.2, GLASS));
    Add(scene, DiskTorus(ro, rd, vec3(5., 2., 0.), normalize(vec3(-5., -2., 0.)), 15., 1., false, DIFFUSE));
    Add(scene, UncappedCylinder(ro, rd, vec3(5., 2., 0.), vec3(5., 2., 0.)*12., 1., identity(), WALL));
    Add(scene, Sphere(ro, rd, vec3(5., 2., 0.)*4., 1., LIGHT));
    #endif

    hit = scene.hit;
    return scene;
}
