vec3 render(vec3 ro, vec3 rd, inout uint state) {
    vec3 rayColor = vec3(1.);
    vec3 incomingLight = vec3(0.);
    float currentIOR = 1.;
    float currentDensity = FOG_DENSITY;
    vec3 currentFogColor = FOG_COLOR;
    bool inside = false;

    int FOG_BOUNCES = 0;

    for (int i = 0; i < MAX_BOUNCES; i+=ONE) {
        bool hit = false;
        traceData dat = trace(ro, rd, hit);

        if (FOG_BOUNCES < (inside?MAX_FOG_BOUNCES_INTERNAL:MAX_FOG_BOUNCES_EXTERNAL) && currentDensity > 0.) {
            float t = -log(hash11(state))/currentDensity;
            if (t < dat.dist || !dat.hit) {
                ro += rd*t;
                rd = randomNormal(state);
                rayColor *= currentFogColor;

                FOG_BOUNCES++;
                continue;
            }
        }

        if (!hit || i == MAX_BOUNCES-1) {
            incomingLight += sky(rd)*rayColor*SKYBOX_BRIGHTNESS;
            break;
        } else {
            ro += rd*dat.dist;
            material mat = getMaterial(ro, dat.matIndex);

            incomingLight += rayColor*mat.emission.rgb*mat.emission.a;
            vec3 roughNormal = normalize(randomNormal(state)*(1.-mat.smoothness)+dat.normal);

            if (hash11(state) < mat.smoothness*pow(max(1.-dot(rd,-dat.normal),0.),4.)) {
                ro += dat.normal*EPSILON;
                rd = reflect(rd, roughNormal);
            } else if (hash11(state) < mat.transparency) {
                float IOR = mat.IOR;
                float density = mat.subsurfaceDensity;
                vec3 fogColor = mat.color;
                if (inside) {
                    IOR = 1.;
                    density = FOG_DENSITY;
                    fogColor = FOG_COLOR;
                } else {
                    if (!mat.subsurfaceScattering) rayColor *= mat.color;
                }
                vec3 ref = refract(rd, roughNormal, currentIOR/IOR);
                if (length(ref) < .5) {
                    ro += roughNormal*EPSILON;
                    rd = reflect(rd, roughNormal);
                } else {
                    ro -= dat.normal*EPSILON;
                    rd = ref;

                    currentIOR = IOR;
                    currentDensity = density;
                    currentFogColor = fogColor;
                    inside = !inside;
                }
            } else if (hash11(state) < mat.metallic) {
                rayColor *= mat.color;
                ro += dat.normal*EPSILON;
                rd = reflect(rd, roughNormal);
            } else {
                rayColor *= mat.color;
                rd = normalize(randomNormal(state)+roughNormal);
                ro += dat.normal*EPSILON;
            }
        }
    }

    return incomingLight;
}
vec3 renderWavelength(vec3 ro, vec3 rd, inout uint state) {
    float wavelength = 330. + hash11(state)*391.;
    vec3 rayColor = wl_rgb(wavelength);
    float intensity = 1.;
    float incomingLight = 0.;
    float currentIOR = 1.;
    float currentDensity = FOG_DENSITY;
    vec3 currentFogColor = FOG_COLOR;
    bool inside = false;

    int FOG_BOUNCES = 0;

    for (int i = 0; i < MAX_BOUNCES; i+=ONE) {
        bool hit = false;
        traceData dat = trace(ro, rd, hit);

        if (FOG_BOUNCES < (inside?MAX_FOG_BOUNCES_INTERNAL:MAX_FOG_BOUNCES_EXTERNAL) && currentDensity > 0.) {
            float t = -log(hash11(state))/currentDensity;
            if (t < dat.dist || !dat.hit) {
                ro += rd*t;
                rd = randomNormal(state);
                intensity *= presence(rayColor,currentFogColor);

                FOG_BOUNCES++;
                continue;
            }
        }

        if (!hit || i == MAX_BOUNCES-1) {
            vec3 col = sky(rd);
            intensity *= presence(rayColor,col);
            incomingLight += intensity*SKYBOX_BRIGHTNESS;
            break;
        } else {
            ro += rd*dat.dist;
            material mat = getMaterial(ro, dat.matIndex);

            incomingLight += intensity*mat.emission.a*(presence(rayColor,mat.emission.rgb));

            vec3 roughNormal = normalize(randomNormal(state)*(1.-mat.smoothness)+dat.normal);

            if (hash11(state) < mat.smoothness*pow(max(1.-dot(rd,-dat.normal),0.),4.)) {
                ro += dat.normal*EPSILON;
                rd = reflect(rd, roughNormal);
            } else if (hash11(state) < mat.transparency) {
                float IOR = mat.IOR;
                float density = mat.subsurfaceDensity;
                vec3 fogColor = mat.color;
                if (inside) {
                    IOR = 1.;
                    density = FOG_DENSITY;
                    fogColor = FOG_COLOR;
                } else {
                    if (!mat.subsurfaceScattering)
                        intensity *= presence(rayColor,mat.color);
                    IOR = dynamicIOR(wavelength, IOR, 1.5e4);
                }
                vec3 ref = refract(rd, roughNormal, currentIOR/IOR);
                if (length(ref) < .5) {
                    ro += roughNormal*EPSILON;
                    rd = reflect(rd, roughNormal);
                } else {
                    ro -= dat.normal*EPSILON;
                    rd = ref;

                    currentIOR = IOR;
                    currentDensity = density;
                    currentFogColor = fogColor;
                    inside = !inside;
                }
            } else if (hash11(state) < mat.metallic) {
                intensity *= presence(rayColor,mat.color);
                ro += dat.normal*EPSILON;
                rd = reflect(rd, roughNormal);
            } else {
                intensity *= presence(rayColor,mat.color);
                rd = normalize(randomNormal(state)+roughNormal);
                ro += dat.normal*EPSILON;
            }
        }
    }

    return 2.5*rayColor*incomingLight*vec3(1.071,1.226,1.232);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 tuv = fragCoord/iResolution.xy;
    vec2 uv = (fragCoord-iResolution.xy*.5)/iResolution.y;
    vec2 m = (iMouse.xy-iResolution.xy*.5)/iResolution.y;

    vec3 ro = vec3(0.,0.,8.);
    ro = rot3D(ro, -m.y*12., -m.x*12.);
    vec3 rd = getRayDir(ro, vec3(0.), uv, 60.);

    vec3 blueNoiseSeed = texelFetch(iChannel3, ivec2(fragCoord) & 0x3FF, 0).xyz;
    #if BLOBBY
    uint state = uint(texelFetch(iChannel2,ivec2(fragCoord),0).r*150.);
    #else
    uint state = uint(fragCoord.x + fragCoord.y*iResolution.x);
    #endif
    hash11(state);
    state = state+uint(iFrame);

    vec3 col = vec3(0.);
    for (int k = min(0,iFrame); k < SAMPLES; k+=ONE) {
        vec3 nrd = rd;
        if (hash11(state) < BLOOM_CHANCE) {
            nrd = normalize(rd+randomNormal(state)*hash11(state)*hash11(state));
        }
        #if RENDER_WAVELENGTHS
        col += renderWavelength(ro, nrd, state);
        #else
        col += render(ro, nrd, state);
        #endif
    }
    col /= float(SAMPLES);

    fragColor = vec4(col,1.);
}

#define TEMPORAL_RENDER 1
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    vec3 col = texture(iChannel0,uv).rgb;
    vec4 returnColor = vec4(col,1.);

    #if TEMPORAL_RENDER == 1
    vec4 prevCol = texture(iChannel1, uv);
    returnColor = vec4(returnColor.rgb+prevCol.rgb,prevCol.a+1.);

    if (iMouse.z > 0.) {
        returnColor = vec4(col,1.);
    }
    #elif TEMPORAL_RENDER == 2
    vec4 prevCol = texture(iChannel1, uv);
    returnColor = vec4(mix(returnColor.rgb,prevCol.rgb,.5),1.);
    #endif

    fragColor = returnColor;
}
